local rowFrames = {}

local function ShowTooltip(self)
    local r = self.row
    if not r then return end
    GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
    if r.kind == "gear" then
        if not pcall(GameTooltip.SetItemByID, GameTooltip, r.itemID) then GameTooltip:AddLine(r.title) end
        GameTooltip:AddLine(" ")
        GameTooltip:AddLine(r.line, 1, 1, 1, true)
        if r.place and r.place ~= "" then GameTooltip:AddLine(r.place, 0.8, 0.8, 0.8) end
        GameTooltip:AddLine(L["Right-click: add to or remove from the wishlist."], 0.5, 0.8, 1)
    elseif r.kind == "quest" then
        local q = r.entry
        GameTooltip:AddLine(q[1], 1, 0.82, 0)
        GameTooltip:AddLine((L["Required level: %d"]):format(q[2]), 1, 1, 1)
        if q[4] ~= "" then GameTooltip:AddLine((L["Start: %s"]):format(q[4]), 1, 1, 1, true) end
        if q[5] ~= "" then GameTooltip:AddLine((L["End: %s"]):format(q[5]), 1, 1, 1, true) end
    else
        GameTooltip:AddLine(r.title, 1, 0.82, 0)
        GameTooltip:AddLine(r.line, 1, 1, 1)
    end
    GameTooltip:AddLine(L["Shift-click: Wowhead link."], 0.5, 0.8, 1)
    GameTooltip:Show()
end

-- Wowhead's Forever pages. An addon cannot open a browser, so the link goes
-- into OxedHub's copy box. Items by id; quests and dungeons by a search on
-- the name, since the map data has no quest ids.
local WOWHEAD = "https://www.wowhead.com/forever/"
local function WowheadURL(r)
    if r.itemID then return WOWHEAD .. "item=" .. r.itemID end
    local name = r.entry and r.entry[1]
    if type(name) ~= "string" or name == "" then return nil end
    local q = name:gsub("[^%w ]", ""):gsub(" +", "+")
    return WOWHEAD .. "search?q=" .. q
end

local function ShowWowhead(r)
    local url = r and WowheadURL(r)
    if url and OxedHub.ShowCopyURLDialog then OxedHub:ShowCopyURLDialog(url, L["Wowhead Link"]) end
end

local function MakeRow(parent, i)
    local r = CreateFrame("Frame", nil, parent)
    r:SetHeight(ROW_H - 4)
    r:SetPoint("TOPLEFT", parent, "TOPLEFT", 0, -(i - 1) * ROW_H)
    r:SetPoint("TOPRIGHT", parent, "TOPRIGHT", 0, -(i - 1) * ROW_H)

    r.bg = r:CreateTexture(nil, "BACKGROUND")
    r.bg:SetAllPoints()
    r.bg:SetColorTexture(1, 1, 1, i % 2 == 0 and 0.04 or 0.08)

    r.icon = r:CreateTexture(nil, "ARTWORK")
    r.icon:SetSize(34, 34)
    r.icon:SetPoint("LEFT", 4, 0)

    r.pin = CreateFrame("Button", nil, r, "UIPanelButtonTemplate")
    r.pin:SetSize(64, 22)
    r.pin:SetPoint("RIGHT", -4, 0)
    -- Gear rows: open this item's quest on the Quests page.
    r.quest = CreateFrame("Button", nil, r, "UIPanelButtonTemplate")
    r.quest:SetSize(64, 22)
    r.quest:SetPoint("RIGHT", r.pin, "LEFT", -4, 0)
    r.quest:SetText(L["Quest"])
    if OxedHub.UI and OxedHub.UI.ApplyRedButtonStyle then
        OxedHub.UI:ApplyRedButtonStyle(r.quest)
    end
    r.quest:Hide()

    local function Line(font, anchor, y)
        local fs = r:CreateFontString(nil, "OVERLAY", font)
        fs:SetPoint("TOPLEFT", anchor, anchor == r.icon and "TOPRIGHT" or "BOTTOMLEFT", anchor == r.icon and 8 or 0, y)
        fs:SetPoint("RIGHT", r.quest, "LEFT", -6, 0)
        fs:SetJustifyH("LEFT")
        fs:SetWordWrap(false)
        return fs
    end
    r.title = Line("GameFontNormal", r.icon, 1)
    r.line = Line("GameFontHighlightSmall", r.title, -2)
    r.place = Line("GameFontDisableSmall", r.line, -2)

    r:EnableMouse(true)
    r:SetScript("OnEnter", ShowTooltip)
    r:SetScript("OnLeave", function() GameTooltip:Hide() end)
    r:SetScript("OnMouseUp", function(self, button)
        local row = self.row
        if button == "LeftButton" and IsShiftKeyDown() then ShowWowhead(row) return end
        if button ~= "RightButton" or not (row and row.itemID) then return end
        settings.wish = settings.wish or {}
        settings.wish[row.itemID] = (not settings.wish[row.itemID]) or nil
        Refresh()
    end)
    rowFrames[i] = r
    return r
end

Refresh = function()
    if not (window and window:IsShown()) then return end
    Calibrate()
    local list = BuildRows()
    local content = window.content
    local shown = math.min(#list, MAX_ROWS)
    for i = 1, shown do
        local row = list[i]
        local r = rowFrames[i] or MakeRow(content, i)
        r.row = row
        r.icon:SetTexture(row.icon)
        local lv = row.level ~= 999 and tostring(row.level) or "?"
        r.title:SetText(("|cffaaaaaa%s|r  %s"):format(lv, row.title))
        r.line:SetText(row.line or "")
        if row.journal then
            r.place:SetText(row.place or "")
            r.pin:SetText(L["Journal"])
            r.pin:SetScript("OnClick", function() OpenJournal(row.journal) end)
            r.pin:Enable()
        else
            r.place:SetText(row.place or PlaceText(row.loc))
            r.pin:SetText(L["Map"])
            r.pin:SetScript("OnClick", function() SetPin(row.entry[1], row.loc) end)
            r.pin:SetEnabled(row.loc ~= nil)
        end
        if row.kind == "gear" and not row.journal and row.entry then
            r.quest:SetScript("OnClick", function()
                focusQuest = row.entry
                settings.mode = "quests"
                Refresh()
            end)
            r.quest:Show()
        else
            r.quest:Hide()
        end
        r:Show()
    end
    for i = shown + 1, #rowFrames do rowFrames[i]:Hide() end
    content:SetHeight(math.max(1, shown * ROW_H))

    local level = PlayerLevel()
    local count = #list > MAX_ROWS and ("%d+"):format(MAX_ROWS) or tostring(#list)
    if settings.mode == "gear" then
        window.summary:SetText(("%s: %s"):format(L[SLOT_LABEL[settings.slot or "all"] or "Best for me"], count))
    elseif focusQuest and settings.mode == "quests" then
        window.summary:SetText(L["Quest"] .. ": " .. tostring(focusQuest[1]))
    else
        window.summary:SetText(("%s: %s"):format(L[MODE_LABEL[settings.mode] or "Quests"], count))
    end
    -- The slot panel: what is worn, and how many upgrades each slot has.
    local gear = settings.mode == "gear"
    window.slotPanel:SetShown(gear)
    window.classButton:SetShown(gear)
    window.scroll:SetPoint("TOPLEFT", gear and 104 or 14, -80)
    if gear then
        window.classButton:SetText(L["Class"] .. ": " .. ClassSetText())
        for _, b in ipairs(window.slotButtons) do
            local tex
            if b.inv then
                local ok, t = pcall(GetInventoryItemTexture, "player", b.inv)
                tex = ok and t or nil
                if not tex and b.slotName then
                    local ok2, _, empty = pcall(GetInventorySlotInfo, b.slotName)
                    tex = ok2 and empty or nil
                end
            end
            if b.icon then b.icon:SetTexture(tex or b.fallback) end
            local n = slotCounts[b.key]
            b.badge:SetText((n and n > 0) and ("|cff40ff40" .. n .. "|r") or "")
            b.sel:SetShown((settings.slot or "all") == b.key)
        end
    end
    window.modeButton:SetText(L["Show"] .. ": " .. L[MODE_LABEL[settings.mode] or "Quests"])
    window.allButton:SetText(settings.showAll and L["Near my level"] or L["Show all"])

    local status
    if geo.state == "done" then
        status = (L["Map matched on %d flight points. Nearest first."]):format(geo.matched)
    else
        status = L["Map positions not available: no flight points matched. Sorted by level."]
    end
    if level and not settings.showAll then
        status = status .. "  " .. (L["Level %d"]):format(level)
    end
    if gear then
        local known = 0
        local seenTitle = {}
        for t in pairs(settings.rewards or {}) do seenTitle[t] = true known = known + 1 end
        for t in pairs(OxedHub.LevelingFindsRewards or {}) do
            if not seenTitle[t] then known = known + 1 end
        end
        status = (L["Rewards known for %d quests, %d dungeon items. Right-click an item to wish for it."]):format(
            known, journalCount.items)
    end
    window.status:SetText(status)
    local emptyText = L["Nothing listed for your level here. Press Show all."]
    if gear and settings.slot == "wish" then
        emptyText = L["The wishlist is empty. Right-click an item in any slot to add it."]
    elseif gear then
        emptyText = L["Nothing known for this slot yet. Talk to quest givers and open quests: their rewards are remembered here."]
    end
    window.empty:SetText(emptyText)
    window.empty:SetShown(#list == 0)
end

local function BuildWindow()
    if window then return end
    local f = CreateFrame("Frame", "OxedHubLevelingFindsWindow", UIParent)
    local Panel = OxedHub.UIComponents and OxedHub.UIComponents.Panel
    if Panel and Panel.ApplyOrnateFrame then
        local shell = CreateFrame("Frame", nil, f, "BackdropTemplate")
        shell:SetAllPoints(f)
        shell:SetFrameLevel(f:GetFrameLevel())
        shell:EnableMouse(false)
        Panel.ApplyOrnateFrame(shell, L["Leveling Finds"], 0.96)
    else
        local bg = f:CreateTexture(nil, "BACKGROUND")
        bg:SetAllPoints()
        bg:SetColorTexture(0, 0, 0, 0.85)
    end
    f.CloseButton = CreateFrame("Button", nil, f, "UIPanelCloseButton")
    f.CloseButton:SetPoint("TOPRIGHT", f, "TOPRIGHT", -3, -3)
    f.CloseButton:SetScript("OnClick", function() f:Hide() end)
    f:SetSize(W, H)
    f:SetPoint(settings.point or "CENTER", UIParent, settings.point or "CENTER", settings.x or 0, settings.y or 0)
    f:SetFrameStrata("DIALOG")
    f:SetClampedToScreen(true)
    f:EnableMouse(true)
    f:SetMovable(true)
    f:RegisterForDrag("LeftButton")
    f:SetScript("OnDragStart", f.StartMoving)
    f:SetScript("OnDragStop", function(self)
        self:StopMovingOrSizing()
        local point, _, _, x, y = self:GetPoint(1)
        settings.point, settings.x, settings.y = point, x, y
    end)
    f:Hide()
    tinsert(UISpecialFrames, "OxedHubLevelingFindsWindow")

    f.summary = f:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge")
    f.summary:SetPoint("TOPLEFT", 18, -36)

    local function Button(w, text, onClick)
        local b = CreateFrame("Button", nil, f, "UIPanelButtonTemplate")
        b:SetSize(w, 22)
        b:SetText(text)
        b:SetScript("OnClick", onClick)
        if OxedHub.UI and OxedHub.UI.ApplyRedButtonStyle then OxedHub.UI:ApplyRedButtonStyle(b) end
        return b
    end
    local opt = Button(70, L["Options"], function() ShowOptions() end)
    opt:SetPoint("TOPRIGHT", -34, -30)
    f.allButton = Button(100, "", function()
        settings.showAll = not settings.showAll
        focusQuest = nil
        Refresh()
    end)
    f.allButton:SetPoint("RIGHT", opt, "LEFT", -4, 0)
    f.modeButton = Button(150, "", function()
        local idx = 1
        for i, m in ipairs(MODES) do if m == settings.mode then idx = i end end
        if focusQuest and settings.mode == "quests" then
            focusQuest = nil   -- leaving the one-quest view: back to the whole list
        else
            settings.mode = MODES[idx % #MODES + 1]
        end
        focusQuest = nil
        if settings.mode == "gear" then ScanJournal() end
        Refresh()
    end)
    f.modeButton:SetPoint("RIGHT", f.allButton, "LEFT", -4, 0)
    -- Which classes' gear to list: a drop-down with a tick per class, so a
    -- warrior can tick Hunter, Rogue and Druid as well as Warrior.
    f.classButton = Button(150, "", nil)
    f.classButton:SetPoint("RIGHT", f.modeButton, "LEFT", -4, 0)
    local menu = CreateFrame("Frame", nil, f, "BackdropTemplate")
    menu:SetFrameStrata("FULLSCREEN_DIALOG")
    menu:SetPoint("TOPLEFT", f.classButton, "BOTTOMLEFT", 0, -2)
    menu:SetSize(170, 24 + (#CLASSES + 1) * 22)
    menu:EnableMouse(true)
    local menuBg = menu:CreateTexture(nil, "BACKGROUND")
    menuBg:SetAllPoints()
    menuBg:SetColorTexture(0.05, 0.04, 0.03, 0.97)
    local menuEdge = menu:CreateTexture(nil, "BORDER")
    menuEdge:SetPoint("TOPLEFT", -1, 1)
    menuEdge:SetPoint("BOTTOMRIGHT", 1, -1)
    menuEdge:SetColorTexture(0.6, 0.45, 0.15, 0.9)
    menuEdge:SetDrawLayer("BACKGROUND", -1)
    menu:Hide()
    menu.rows = {}

    local function Picked()
        if type(settings.planClasses) ~= "table" then settings.planClasses = {} end
        return settings.planClasses
    end
    local function MenuRefresh()
        local set = {}
        for _, c in ipairs(ClassSet()) do set[c] = true end
        for _, row in ipairs(menu.rows) do
            if row.cls then
                row.tick:SetShown(set[row.cls] == true)
                row.text:SetText(ClassName(row.cls) .. (row.cls == PlayerClass() and ("  |cff888888" .. L["(you)"] .. "|r") or ""))
            end
        end
    end
    local function MenuRow(i, label, onClick)
        local row = CreateFrame("Button", nil, menu)
        row:SetHeight(20)
        row:SetPoint("TOPLEFT", 6, -6 - (i - 1) * 22)
        row:SetPoint("TOPRIGHT", -6, -6 - (i - 1) * 22)
        local hl = row:CreateTexture(nil, "HIGHLIGHT")
        hl:SetAllPoints()
        hl:SetColorTexture(1, 0.82, 0.3, 0.15)
        row.tick = row:CreateTexture(nil, "ARTWORK")
        row.tick:SetSize(16, 16)
        row.tick:SetPoint("LEFT", 2, 0)
        row.tick:SetTexture("Interface\\Buttons\\UI-CheckBox-Check")
        row.tick:Hide()
        row.text = row:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
        row.text:SetPoint("LEFT", 22, 0)
        row.text:SetText(label or "")
        row:SetScript("OnClick", onClick)
        menu.rows[#menu.rows + 1] = row
        return row
    end
    for i, cls in ipairs(CLASSES) do
        local row = MenuRow(i, nil, nil)
        row.cls = cls
        row:SetScript("OnClick", function()
            local pick = Picked()
            -- First tick on a fresh list keeps the class shown until now.
            if not next(pick) then
                for _, c in ipairs(ClassSet()) do pick[c] = true end
            end
            pick[cls] = (not pick[cls]) or nil
            settings.planClass = false
            MenuRefresh()
            Refresh()
        end)
    end
    MenuRow(#CLASSES + 1, "|cffffd100" .. L["Only my class"] .. "|r", function()
        wipe(Picked())
        settings.planClass = false
        MenuRefresh()
        Refresh()
    end)
    local hint = menu:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
    hint:SetPoint("BOTTOM", 0, 6)
    hint:SetText(L["Tick every class whose gear you wear."])
    f.classButton:SetScript("OnClick", function()
        MenuRefresh()
        menu:SetShown(not menu:IsShown())
    end)
    f:HookScript("OnHide", function() menu:Hide() end)

    -- Slot panel: worn items in character sheet order, and three lists.
    local panel = CreateFrame("Frame", nil, f)
    panel:SetPoint("TOPLEFT", 14, -80)
    panel:SetSize(84, 420)
    f.slotPanel = panel
    f.slotButtons = {}
    local function SlotButton(key, x, y, def, text)
        local b = CreateFrame("Button", nil, panel)
