-- ── Quest scanner (/oxfind scan) ────────────────────────────────────────────
-- Asks the server for one quest at a time by number and writes down its
-- title and item rewards in settings.scanned[questID]. Slow on purpose
-- (about 4 a second, one request in flight) so the server never sees a burst.
-- .outsource/questscan/export.js turns the result into LevelingFindsRewards.lua.

local scan = { on = false }
local SCAN_GAP, SCAN_WAIT = 0.25, 2

local function ItemIDFromInfo(fn, i, questID)
    local ok, _, _, _, _, _, itemID = pcall(fn, i, questID)
    return (ok and type(itemID) == "number" and itemID > 0) and itemID or nil
end

local function ReadScannedQuest(questID)
    if not (C_QuestLog and C_QuestLog.GetTitleForQuestID) then return end
    local ok, title = pcall(C_QuestLog.GetTitleForQuestID, questID)
    if not ok or type(title) ~= "string" or title == "" or Secret(title) then return end
    local choices, given = {}, {}
    if GetNumQuestLogChoices and GetQuestLogChoiceInfo then
        local okN, n = pcall(GetNumQuestLogChoices, questID, false)
        for i = 1, (okN and type(n) == "number") and n or 0 do
            choices[#choices + 1] = ItemIDFromInfo(GetQuestLogChoiceInfo, i, questID)
        end
    end
    if GetNumQuestLogRewards and GetQuestLogRewardInfo then
        local okN, n = pcall(GetNumQuestLogRewards, questID)
        for i = 1, (okN and type(n) == "number") and n or 0 do
            given[#given + 1] = ItemIDFromInfo(GetQuestLogRewardInfo, i, questID)
        end
    end
    settings.scanned = settings.scanned or {}
    settings.scanned[questID] = { t = title, c = choices, r = given }
    scan.found = scan.found + 1
    if #choices > 0 or #given > 0 then
        scan.items = scan.items + 1
        settings.rewards[title] = settings.rewards[title] or { c = choices, r = given }
    end
end

-- Rewards come in after the title: ask for them, then wait until the client
-- says it has them (HaveQuestRewardData) or give up after a few seconds.
-- The first scan read too early and missed most quests' items.
local function AskRewards(questID)
    if C_TaskQuest and C_TaskQuest.RequestPreloadRewardData then
        pcall(C_TaskQuest.RequestPreloadRewardData, questID)
    end
end

local function HaveRewards(questID)
    if not HaveQuestRewardData then return nil end
    local ok, v = pcall(HaveQuestRewardData, questID)
    if not ok or Secret(v) then return nil end
    return v and true or false
end

local REWARD_WAIT, REWARD_STEP = 4, 0.25

local ScanNext
local function ScanDone(questID, loaded)
    if not scan.on or scan.waiting ~= questID then return end
    scan.waiting = nil
    if not loaded then C_Timer.After(SCAN_GAP, ScanNext) return end
    AskRewards(questID)
    local waited = 0
    local function Try()
        if not scan.on then return end
        local have = HaveRewards(questID)
        if have == false and waited < REWARD_WAIT then
            waited = waited + REWARD_STEP
            C_Timer.After(REWARD_STEP, Try)
            return
        end
        if have then scan.ready = (scan.ready or 0) + 1 end
        ReadScannedQuest(questID)
        C_Timer.After(SCAN_GAP, ScanNext)
    end
    C_Timer.After(REWARD_STEP, Try)
end

ScanNext = function()
    if not scan.on then return end
    local id
    if scan.list then
        -- /oxfind rescan: only the quests that came back without items.
        id = scan.list[scan.idx]
        if not id then
            scan.on = false
            settings.rescanIdx = nil
            print(PREFIX .. (L["Rescan finished: %d quests checked, %d now with item rewards."]):format(
                #scan.list, scan.items))
            return
        end
        scan.idx = scan.idx + 1
        settings.rescanIdx = scan.idx
        if scan.idx % 100 == 0 then
            print(PREFIX .. (L["Rescanning %d of %d: %d with item rewards so far."]):format(
                scan.idx, #scan.list, scan.items))
        end
    else
        id = scan.id
        if id > scan.to then
            scan.on = false
            print(PREFIX .. (L["Scan finished at quest %d: %d quests found, %d with item rewards."]):format(
                scan.to, scan.found, scan.items))
            return
        end
        scan.id = id + 1
        settings.scanPos = scan.id
        if (id - scan.from) % 250 == 0 and id ~= scan.from then
            print(PREFIX .. (L["Scanning quest %d of %d: %d found, %d with item rewards."]):format(
                id, scan.to, scan.found, scan.items))
        end
    end
    scan.waiting = id
    pcall(C_QuestLog.RequestLoadQuestByID, id)
    -- Quests the server never answers for: move on after a while.
    C_Timer.After(SCAN_WAIT, function() ScanDone(id, true) end)
end

local function ScanCommand(args)
    if args == "stop" then
        scan.on = false
        print(PREFIX .. (L["Scan stopped at quest %d. /oxfind scan continues from there."]):format(settings.scanPos or 1))
        return
    end
    if not (C_QuestLog and C_QuestLog.RequestLoadQuestByID and C_QuestLog.GetTitleForQuestID) then
        print(PREFIX .. L["This client cannot load quests by number."])
        return
    end
    if not running then
        print(PREFIX .. L["switched off. Switch it on in OxedHub's Modules page first."])
        return
    end
    if args == "rescan" then
        local list = {}
        for id, q in pairs(settings.scanned or {}) do
            if type(q) == "table" and q.t and #(q.c or {}) == 0 and #(q.r or {}) == 0 then list[#list + 1] = id end
        end
        table.sort(list)
        scan.list, scan.idx = list, math.min(settings.rescanIdx or 1, #list + 1)
        scan.found, scan.items, scan.ready, scan.on = 0, 0, 0, true
        print(PREFIX .. (L["Rescanning %d quests that showed no items, from number %d. /oxfind scan stop to stop."]):format(
            #list, scan.idx))
        ScanNext()
        return
    end
    scan.list = nil
    local from, to = args:match("^(%d+)%s+(%d+)$")
    from, to = tonumber(from), tonumber(to)
    if not from then
        from, to = settings.scanPos or 1, 15000
    end
    scan.from, scan.to, scan.id = from, math.max(from, to), from
    scan.found, scan.items, scan.on = 0, 0, true
    settings.scanned = settings.scanned or {}
    print(PREFIX .. (L["Scanning quests %d to %d, about 4 a second. /oxfind scan stop to stop."]):format(from, scan.to))
    ScanNext()
end

SLASH_OXEDLEVELFINDS1 = "/oxfind"
SLASH_OXEDLEVELFINDS2 = "/levelfinds"
SlashCmdList.OXEDLEVELFINDS = function(msg)
    msg = (msg or ""):lower():match("^%s*(.-)%s*$")
    local scanArgs = msg:match("^scan%s*(.*)$")
    if msg == "rescan" then ScanCommand("rescan")
    elseif scanArgs then ScanCommand(scanArgs)
    elseif msg == "options" or msg == "config" then ShowOptions()
    else Toggle() end
end

-- ── Upgrades on item tooltips ───────────────────────────────────────────────
-- One line under the game's own, only when the item beats what is worn. The
-- hook cannot be taken back, so it is installed once and asks `running`.

local function Wearing(itemID)
    if not GetInventoryItemID then return false end
    for slot = 1, 18 do
        local ok, id = pcall(GetInventoryItemID, "player", slot)
        if ok and not Secret(id) and id == itemID then return true end
    end
    return false
end

local function OnItemTooltip(tooltip, data)
    if not running or not settings or not settings.tooltipLine then return end
    if tooltip ~= GameTooltip and tooltip ~= ItemRefTooltip then return end
    local id
    if type(data) == "table" then id = data.id end
    if Secret(id) then return end
    if not id and tooltip.GetItem then
        local _, link = tooltip:GetItem()
        id = LinkID(link)
    end
    if type(id) ~= "number" then return end
    if Wearing(id) then return end
    local gain = Upgrade(id)
    local best = IsBestNow(id)
    local wished = IsWished(id)
    if type(gain) ~= "number" and not best and not wished then return end
    local parts = {}
    if type(gain) == "number" then parts[#parts + 1] = UpgradeText(gain, false) end
    if best then parts[#parts + 1] = "|cffffd100" .. L["Best now for your level"] .. "|r" end
    if wished then parts[#parts + 1] = "|TInterface\\COMMON\\FavoritesIcon:14:14|t" .. L["On your wishlist"] end
    if GetItemCount then
        local okC, bags = pcall(GetItemCount, id)
        local okB, all = pcall(GetItemCount, id, true)
        if okC and type(bags) == "number" and bags > 0 then
            parts[#parts + 1] = "|cff88cc88" .. L["In your bags"] .. "|r"
        elseif okB and type(all) == "number" and all > 0 then
            parts[#parts + 1] = "|cff88cc88" .. L["In your bank"] .. "|r"
        end
    end
    tooltip:AddLine("|cff33ff99" .. L["Leveling Finds"] .. ":|r " .. table.concat(parts, "  "), 1, 1, 1, true)
end

local tooltipHooked = false
local function HookTooltips()
    if tooltipHooked then return end
    tooltipHooked = true
    -- A tooltip must never break because of us: every call is in pcall.
    local itemType = Enum and Enum.TooltipDataType and Enum.TooltipDataType.Item
    if TooltipDataProcessor and TooltipDataProcessor.AddTooltipPostCall and itemType then
        pcall(TooltipDataProcessor.AddTooltipPostCall, itemType, function(tooltip, data)
            pcall(OnItemTooltip, tooltip, data)
        end)
        return
    end
    for _, tooltip in ipairs({ GameTooltip, ItemRefTooltip }) do
        if tooltip and tooltip.HookScript then
            pcall(tooltip.HookScript, tooltip, "OnTooltipSetItem", function(self)
                pcall(OnItemTooltip, self)
            end)
        end
    end
end

-- ── The best reward in the quest window ─────────────────────────────────────
-- Among a quest's choices: the biggest upgrade, in green; with no upgrade at
-- all, the one a vendor pays the most for, in gold.

local pickMark
local pickSaid       -- the quest already named in chat, so a retry stays quiet
local pickTries = 0

local function RewardButton(i)
    if QuestInfo_GetRewardButton and QuestInfoFrame and QuestInfoFrame.rewardsFrame then
        local ok, button = pcall(QuestInfo_GetRewardButton, QuestInfoFrame.rewardsFrame, i)
        if ok and button then return button end
    end
    return _G["QuestInfoRewardsFrameQuestInfoItem" .. i] or _G["QuestInfoItem" .. i]
end

local function HidePick()
    if pickMark then pickMark:Hide() end
end

local function ShowPick(button, r, g, b, icon)
    if not pickMark then
        pickMark = CreateFrame("Frame")
        pickMark.edges = {}
        for i = 1, 4 do pickMark.edges[i] = pickMark:CreateTexture(nil, "OVERLAY") end
        local e = pickMark.edges
        e[1]:SetPoint("TOPLEFT") e[1]:SetPoint("TOPRIGHT") e[1]:SetHeight(2)
        e[2]:SetPoint("BOTTOMLEFT") e[2]:SetPoint("BOTTOMRIGHT") e[2]:SetHeight(2)
        e[3]:SetPoint("TOPLEFT") e[3]:SetPoint("BOTTOMLEFT") e[3]:SetWidth(2)
        e[4]:SetPoint("TOPRIGHT") e[4]:SetPoint("BOTTOMRIGHT") e[4]:SetWidth(2)
        pickMark.icon = pickMark:CreateTexture(nil, "OVERLAY")
        pickMark.icon:SetSize(16, 16)
        pickMark.icon:SetPoint("TOPRIGHT", -2, -2)
    end
    pickMark:SetParent(button)
    pickMark:ClearAllPoints()
    pickMark:SetAllPoints(button)
    pickMark:SetFrameLevel(button:GetFrameLevel() + 5)
    for _, edge in ipairs(pickMark.edges) do edge:SetColorTexture(r, g, b, 0.9) end
    pickMark.icon:SetTexture(icon)
    pickMark:Show()
end

local MarkBestReward
MarkBestReward = function(event)
    HidePick()
    HideToasts()
    if not running or not (settings.rewardMark or settings.rewardChat) then return end
    if not (GetNumQuestChoices and GetQuestItemLink) then return end
    local okN, n = pcall(GetNumQuestChoices)
    if not okN or type(n) ~= "number" or n < 2 then return end
    local info = (C_Item and C_Item.GetItemInfo) or GetItemInfo

    local bestGain, gainIndex, bestPrice, priceIndex
    local links, missing = {}, false
    for i = 1, n do
        local okL, link = pcall(GetQuestItemLink, "choice", i)
        local id = okL and LinkID(link)
        if not id then
            missing = true
        else
            links[i] = link
            local gain = Upgrade(id)
            if type(gain) == "number" and (not bestGain or gain > bestGain) then bestGain, gainIndex = gain, i end
            local okP, price = pcall(function() return (select(11, info(id))) end)
            if okP and type(price) == "number" and price > 0 and (not bestPrice or price > bestPrice) then
                bestPrice, priceIndex = price, i
            end
        end
    end
    -- The window can open before the game has the items: look again shortly.
    if missing and pickTries < 3 then
        pickTries = pickTries + 1
        C_Timer.After(0.5, function() pcall(MarkBestReward, event) end)
        return
    end

    local index = gainIndex or priceIndex
    if not index then return end
    if settings.rewardMark then
        local button = RewardButton(index)
        if button and button.IsVisible and button:IsVisible() then
            if gainIndex then
                ShowPick(button, 0.25, 1, 0.25, "Interface\\Buttons\\UI-MicroStream-Green")
            else
                ShowPick(button, 1, 0.82, 0, "Interface\\MoneyFrame\\UI-GoldIcon")
            end
        end
    end
    if settings.rewardChat and event == "QUEST_COMPLETE" then
        local okT, title = pcall(GetTitleText)
        local key = (okT and type(title) == "string" and not Secret(title)) and title or "?"
        if pickSaid ~= key then
            pickSaid = key
            if gainIndex then
                print(PREFIX .. (L["Best reward: %s (%s)"]):format(links[index], UpgradeText(bestGain, false)))
            else
                print(PREFIX .. (L["No upgrade among the rewards. %s sells for the most."]):format(links[index]))
            end
        end
    end
end

-- ── A new best item for the level ───────────────────────────────────────────
-- At login and on every level: the best item per slot that can be had now.
-- A slot whose answer changed since it was last announced is said once, in
-- chat and across the screen. settings.bisSeen[character][slot] = itemID,
-- made after binding, never in DEFAULTS.

local BIS_LINES = 4      -- more than this many at once are summed up in one line

local function CharKey()
    local okN, name = pcall(UnitName, "player")
    local okR, realm = pcall(GetRealmName)
    if not okN or Secret(name) or type(name) ~= "string" then return "?" end
    return name .. "-" .. ((okR and type(realm) == "string" and not Secret(realm)) and realm or "?")
end

-- ── Notifications on screen ─────────────────────────────────────────────────
-- A card per new best item, stacked like a phone's notifications: newest on
-- top, each staying until it is closed. Click one: the list on Best now.
-- The heading above the stack drags it and clears it all. Only for this
-- session; the chat lines stay as the record.
--   Leveling Finds  3            [Clear all]
--   [icon] Best Chest, level 24           x
--          Robe of Evocation  +12.4
--          Quest: The Defias Brotherhood

local TOAST_W, TOAST_H, TOAST_GAP = 300, 54, 4
local TOAST_SHOWN = 5        -- cards drawn; the rest wait under "and N more"

local toastHolder
local toastCards = {}        -- frames, reused
local toastList = {}         -- what is waiting, newest first

local LayoutToasts

local function OpenBestNow()
    settings.mode = "gear"
    settings.slot = "bis"
    if window and window:IsShown() then Refresh() else Toggle() end
end

local function DismissToast(entry)
    for i, e in ipairs(toastList) do
        if e == entry then
            table.remove(toastList, i)
            break
        end
    end
    LayoutToasts()
end

local function SaveToastPlace()
    local point, _, rel, x, y = toastHolder:GetPoint()
    settings.toastPoint, settings.toastRel = point, rel
    settings.toastX, settings.toastY = x, y
end

local function BuildToastHolder()
    if toastHolder then return end
    local h = CreateFrame("Frame", "OxedHubLevelingToasts", UIParent)
    h:SetSize(TOAST_W, 20)
    h:SetFrameStrata("HIGH")
    h:SetClampedToScreen(true)
    h:SetMovable(true)
    h:EnableMouse(true)
    h:RegisterForDrag("LeftButton")
    h:SetScript("OnDragStart", h.StartMoving)
    h:SetScript("OnDragStop", function(self)
        self:StopMovingOrSizing()
        SaveToastPlace()
    end)
    h:SetPoint(settings.toastPoint or "TOPRIGHT", UIParent, settings.toastRel or "TOPRIGHT",
        settings.toastX or -220, settings.toastY or -180)

    h.title = h:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
    h.title:SetPoint("LEFT", 4, 0)

    local clear = CreateFrame("Button", nil, h)
    clear:SetSize(70, 18)
    clear:SetPoint("RIGHT", -2, 0)
    clear.text = clear:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
    clear.text:SetAllPoints()
    clear.text:SetText(L["Clear all"])
    clear:SetHighlightTexture("Interface\\Buttons\\UI-Common-MouseHilight", "ADD")
    clear:SetScript("OnClick", function()
        wipe(toastList)
        LayoutToasts()
    end)

    h.more = h:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
    h:SetScript("OnEnter", function(self)
        GameTooltip:SetOwner(self, "ANCHOR_TOP")
        GameTooltip:AddLine(L["Leveling Finds"])
        GameTooltip:AddLine(L["Drag to move. Click a card for the list, x or right-click to close it."], 1, 1, 1, true)
        GameTooltip:Show()
    end)
    h:SetScript("OnLeave", function() GameTooltip:Hide() end)
    h:Hide()
    toastHolder = h
end

local function ToastCard(i)
    local card = toastCards[i]
    if card then return card end
    card = CreateFrame("Button", nil, toastHolder, "BackdropTemplate")
    card:SetSize(TOAST_W, TOAST_H)
    card:SetBackdrop({
        bgFile = "Interface\\Buttons\\WHITE8X8", edgeFile = "Interface\\Tooltips\\UI-Tooltip-Border",
        edgeSize = 12, insets = { left = 3, right = 3, top = 3, bottom = 3 },
    })
    card:SetBackdropColor(0.06, 0.06, 0.08, 0.92)
    card:SetBackdropBorderColor(0.25, 0.9, 0.35, 1)
    card:RegisterForClicks("LeftButtonUp", "RightButtonUp")

    card.icon = card:CreateTexture(nil, "ARTWORK")
    card.icon:SetSize(36, 36)
    card.icon:SetPoint("LEFT", 9, 0)
    card.icon:SetTexCoord(0.08, 0.92, 0.08, 0.92)

    card.head = card:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
    card.head:SetPoint("TOPLEFT", card.icon, "TOPRIGHT", 8, 1)
    card.head:SetPoint("RIGHT", -24, 0)
    card.head:SetJustifyH("LEFT")
    card.item = card:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
    card.item:SetPoint("TOPLEFT", card.head, "BOTTOMLEFT", 0, -2)
    card.item:SetPoint("RIGHT", -10, 0)
    card.item:SetJustifyH("LEFT")
    card.item:SetWordWrap(false)
    card.from = card:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
    card.from:SetPoint("TOPLEFT", card.item, "BOTTOMLEFT", 0, -2)
    card.from:SetPoint("RIGHT", -10, 0)
    card.from:SetJustifyH("LEFT")
    card.from:SetWordWrap(false)

    local close = CreateFrame("Button", nil, card, "UIPanelCloseButton")
    close:SetSize(22, 22)
    close:SetPoint("TOPRIGHT", 1, 1)
    close:SetScript("OnClick", function() if card.entry then DismissToast(card.entry) end end)

    -- In from the side, like a phone's banner. Only the card's own position
    -- moves, nothing secret is shown here.
    card.slide = card:CreateAnimationGroup()
    local move = card.slide:CreateAnimation("Translation")
    move:SetOffset(-40, 0)
    move:SetDuration(0)
    move:SetOrder(1)
    local back = card.slide:CreateAnimation("Translation")
    back:SetOffset(40, 0)
    back:SetDuration(0.25)
    back:SetSmoothing("OUT")
    back:SetOrder(2)

    card:SetScript("OnClick", function(self, button)
        local entry = self.entry
        if not entry then return end
        if button == "LeftButton" then OpenBestNow() end
        DismissToast(entry)
    end)
    card:SetScript("OnEnter", function(self)
        if not (self.entry and self.entry.itemID) then return end
        GameTooltip:SetOwner(self, "ANCHOR_LEFT")
        pcall(GameTooltip.SetItemByID, GameTooltip, self.entry.itemID)
        GameTooltip:AddLine(" ")
        GameTooltip:AddLine(L["Click: the list. Right-click: close."], 0.5, 0.8, 1)
        GameTooltip:Show()
    end)
    card:SetScript("OnLeave", function() GameTooltip:Hide() end)
    toastCards[i] = card
    return card
end

LayoutToasts = function()
    if not toastHolder then return end
    local total = #toastList
    if total == 0 or not running then
        toastHolder:Hide()
        return
    end
    toastHolder.title:SetText(("%s  |cffffffff%d|r"):format(L["Leveling Finds"], total))
    local shown = math.min(total, TOAST_SHOWN)
    for i = 1, shown do
        local entry = toastList[i]
        local card = ToastCard(i)
        local fresh = card.entry ~= entry
        card.entry = entry
        card.icon:SetTexture(entry.icon or "Interface\\Icons\\INV_Misc_QuestionMark")
        card.head:SetText(entry.head)
        card.item:SetText(entry.item)
        card.from:SetText(entry.from)
        card:ClearAllPoints()
        card:SetPoint("TOPLEFT", toastHolder, "BOTTOMLEFT", 0, -2 - (i - 1) * (TOAST_H + TOAST_GAP))
        card:Show()
        if fresh and entry.isNew then
            entry.isNew = nil
            card.slide:Stop()
            card.slide:Play()
        end
    end
    for i = shown + 1, #toastCards do
        toastCards[i].entry = nil
        toastCards[i]:Hide()
    end
    local more = toastHolder.more
    if total > shown then
        more:ClearAllPoints()
        more:SetPoint("TOP", toastCards[shown], "BOTTOM", 0, -4)
        more:SetText((L["and %d more"]):format(total - shown))
        more:Show()
    else
        more:Hide()
    end
    toastHolder:Show()
end

-- One card: what, for which slot, from where.
local function PushToast(entry)
    if not (settings and settings.bisToasts) then return end
    BuildToastHolder()
    entry.isNew = true
    table.insert(toastList, 1, entry)
    LayoutToasts()
end

HideToasts = function()
    wipe(toastList)
    LayoutToasts()
end

-- quiet: only ask the game for the items, so the real pass finds them loaded.
local function CheckBis(quiet)
    if not running or not settings or not settings.bisAlert then return end
    local best, level = BestNow()
    if quiet or not level then return end
    if type(settings.bisSeen) ~= "table" then settings.bisSeen = {} end
    local key = CharKey()
    local seen = settings.bisSeen[key]
    if type(seen) ~= "table" then
        seen = {}
        settings.bisSeen[key] = seen
    end
    local fresh = {}
    for group, b in pairs(best) do
        if seen[group] ~= b.itemID then fresh[#fresh + 1] = { group = group, best = b } end
    end
    if #fresh == 0 then return end
    table.sort(fresh, function(a, b) return a.best.gain > b.best.gain end)

    local fn = (C_Item and C_Item.GetItemInfo) or GetItemInfo
    -- Oldest first, so the biggest gain ends up on top of the stack.
    for i = #fresh, 1, -1 do
        local item = fresh[i]
        seen[item.group] = item.best.itemID
        local b = item.best
        local ok, _, link, _, _, _, _, _, _, _, icon = pcall(fn, b.itemID)
        local shown = (ok and type(link) == "string") and link or (QualityColour(b.quality) .. b.name .. "|r")
        local from
        if b.src.quest then
            from = (L["Quest: %s"]):format(b.src.quest[1])
        else
            from = (L["%s, in %s"]):format(b.src.journal.boss or "?", b.src.journal.dungeon or "?")
        end
        local slot = L[SLOT_LABEL[item.group] or item.group]
        if i <= BIS_LINES then
            print(PREFIX .. (L["Best %s at level %d: %s  %s  %s"]):format(
                slot, level, shown, UpgradeText(b.gain, false), from))
        end
        PushToast({
            itemID = b.itemID, icon = ok and icon or nil,
            head = (L["Best %s, level %d"]):format(slot, level),
            item = shown .. "  " .. UpgradeText(b.gain, false),
            from = from,
        })
    end
    if #fresh > BIS_LINES then
        print(PREFIX .. (L["And %d more slots. Type /oxfind and press Best now."]):format(#fresh - BIS_LINES))
    end
    -- The cards say it already; the line across the screen is for those
    -- who switched them off.
    if not settings.bisToasts and UIErrorsFrame and UIErrorsFrame.AddMessage then
        UIErrorsFrame:AddMessage((L["Leveling Finds: %d new best items for level %d"]):format(#fresh, level), 1, 0.82, 0)
    end
    if settings.bisSound and settings.bisSound ~= "None" and OxedHub.ModuleAPI and OxedHub.ModuleAPI.PlaySound then
        OxedHub.ModuleAPI:PlaySound(settings.bisSound)
    end
end

-- ── Trying the notifications ────────────────────────────────────────────────
-- /oxfind test: three sample cards, from the items you wear, marked as a test.
-- /oxfind bisreset: forget what was announced for this character and look
-- again, so the real cards for your level come up at once.

local function TestToasts()
    if not settings.bisToasts then
        print(PREFIX .. L["Cards are switched off in the options."])
        return
    end
    local fn = (C_Item and C_Item.GetItemInfo) or GetItemInfo
    local made = 0
    for _, slot in ipairs({ 5, 16, 1, 7, 3, 10 }) do
        if made >= 3 then break end
        local okID, id = pcall(GetInventoryItemID, "player", slot)
        if okID and type(id) == "number" and not Secret(id) then
            local ok, _, link, _, _, _, _, _, _, _, icon = pcall(fn, id)
            if ok and type(link) == "string" then
                made = made + 1
                PushToast({
                    itemID = id, icon = icon,
                    head = L["Test notification"],
                    item = link .. "  " .. UpgradeText(made * 5, false),
                    from = L["Not a real upgrade. Click or close it."],
                })
            end
        end
    end
    if made == 0 then
        PushToast({
            head = L["Test notification"], item = L["Leveling Finds"],
            from = L["Not a real upgrade. Click or close it."],
        })
    end
end

local function ResetBis()
    if type(settings.bisSeen) == "table" then settings.bisSeen[CharKey()] = nil end
    if not settings.bisAlert then
        print(PREFIX .. L["The best item alert is switched off in the options."])
        return
    end
    print(PREFIX .. L["Looking again for the best items at your level..."])
    -- Twice, as at login: the first pass makes the game load the items.
    pcall(CheckBis, true)
    C_Timer.After(3, function()
        local before = #toastList
        pcall(CheckBis)
        if #toastList == before then print(PREFIX .. L["Nothing better than what you wear at your level."]) end
    end)
end

do
    local base = SlashCmdList.OXEDLEVELFINDS
    SlashCmdList.OXEDLEVELFINDS = function(msg)
        local cmd = (msg or ""):lower():match("^%s*(.-)%s*$")
        if not running then return base(msg) end
        if cmd == "test" then TestToasts()
        elseif cmd == "bisreset" then ResetBis()
        else base(msg) end
    end
end

-- ── Events ──────────────────────────────────────────────────────────────────

local refreshQueued = false
local function QueueRefresh(delay)
    if not running or refreshQueued or not (window and window:IsShown()) then return end
    refreshQueued = true
    C_Timer.After(delay or 0.3, function()
        refreshQueued = false
        if running then Refresh() end
    end)
end

local logQueued = false
local function QueueLogCapture()
    if logQueued then return end
    logQueued = true
    C_Timer.After(1, function()
        logQueued = false
        if running then CaptureQuestLog() QueueRefresh(0) end
    end)
end

events:SetScript("OnEvent", function(_, event, a1, a2)
    if not running then return end
    if event == "QUEST_DATA_LOAD_RESULT" then
        if scan.on and a1 == scan.waiting then ScanDone(a1, a2 and true or false) end
        return
    end
    if event == "QUEST_FINISHED" then
        HidePick()
        pickSaid = nil
        return
    end
    if event == "PLAYER_LEVEL_UP" then
        -- The new level reaches UnitLevel a moment after the event.
        C_Timer.After(3, function() pcall(CheckBis) end)
    end
    if event == "QUEST_DETAIL" or event == "QUEST_COMPLETE" then
        CaptureGossipQuest()
        pickTries = 0
        -- The window lays its reward buttons out after the event.
        C_Timer.After(0.1, function() pcall(MarkBestReward, event) end)
    elseif event == "QUEST_ACCEPTED" or event == "PLAYER_ENTERING_WORLD" then
        QueueLogCapture()
    end
    QueueRefresh(0.3)
end)

local EVENTS = { "GET_ITEM_INFO_RECEIVED", "PLAYER_LEVEL_UP", "ZONE_CHANGED_NEW_AREA", "QUEST_DETAIL",
                 "QUEST_COMPLETE", "QUEST_ACCEPTED", "PLAYER_ENTERING_WORLD", "PLAYER_EQUIPMENT_CHANGED",
                 "QUEST_DATA_LOAD_RESULT", "QUEST_FINISHED" }

-- Distances change as the player moves: re-sort every few seconds while open.
local ticker
local function Start()
    if running then return end
    running = true
    for _, e in ipairs(EVENTS) do pcall(events.RegisterEvent, events, e) end
    HookTooltips()
    -- Once to make the game load the items, once more to say what is new.
    C_Timer.After(6, function() pcall(CheckBis, true) end)
    C_Timer.After(14, function() pcall(CheckBis) end)
    if C_Timer.NewTicker then
        ticker = C_Timer.NewTicker(5, function() QueueRefresh(0) end)
    end
    QueueLogCapture()
end

local function Stop()
    running = false
    events:UnregisterAllEvents()
    if ticker then ticker:Cancel() ticker = nil end
    HidePick()
    if window then window:Hide() end
end

-- ── Login ───────────────────────────────────────────────────────────────────

MinimapIcon = function()
    if minimapIcon or not settings then return minimapIcon end
    local API = OxedHub.ModuleAPI
    minimapIcon = API and API.MinimapButton and API:MinimapButton({
        key = "levelingfinds", label = L["Leveling Finds"], icon = "Interface\\Icons\\INV_Misc_Map_01", config = settings,
        hint = L["Click: the list. Right-click: options."],
        onClick = function(mouse)
            if mouse == "RightButton" then ShowOptions() else Toggle() end
        end,
    })
    return minimapIcon
end

local loginFrame = CreateFrame("Frame")
loginFrame:RegisterEvent("PLAYER_LOGIN")
loginFrame:SetScript("OnEvent", function(self)
    self:UnregisterEvent("PLAYER_LOGIN")
    -- Forever's quests and zones; nothing to show on the main game.
    if OxedHub.IsMainline then return end
    OxedHubDB = OxedHubDB or {}
    OxedHubDB.modules = OxedHubDB.modules or {}
    local config = OxedHubDB.modules.levelingfinds
    if type(config) ~= "table" then
        config = {}
        OxedHubDB.modules.levelingfinds = config
    end
    for key, value in pairs(DEFAULTS) do
        if config[key] == nil then config[key] = value end
    end
    if type(config.rewards) ~= "table" then config.rewards = {} end
    if type(config.wish) ~= "table" then config.wish = {} end
    if type(config.planClasses) ~= "table" then config.planClasses = {} end
    if type(config.bisSeen) ~= "table" then config.bisSeen = {} end
    if config.mode ~= "gear" and config.mode ~= "quests" and config.mode ~= "dungeons" then config.mode = "gear" end
    settings = config

    if not OxedHub.ModuleAPI then return end
    OxedHub.ModuleAPI:Register({
        id       = "levelingfinds",
        name     = "Leveling Finds",
        version  = "2.11.0",
        updated  = 20261114.1,  -- two-handers against both hands, why not yet, weapons choice, richer tooltip
        author   = "Oxed",
        category = "quests",
        keywords = { "leveling", "levelling", "quest", "dungeon", "loot", "map", "forever", "mapgenie", "find" },
        desc     = "Quests and dungeons for your level, nearest first, with a map pin, and the gear they give.",
        icon     = "Interface\\Icons\\INV_Misc_Map_01",
        defaults = DEFAULTS,
        quick = {
            { text = L["Show or hide"], func = function() Toggle() end },
        },
        OnOptionsShow = function() ShowOptions() end,
        OnEnable = function(_, cfg)
            settings = cfg
            if type(settings.rewards) ~= "table" then settings.rewards = {} end
            if type(settings.wish) ~= "table" then settings.wish = {} end
            if type(settings.planClasses) ~= "table" then settings.planClasses = {} end
            local icon = MinimapIcon()
            if icon then icon:Apply(true) end
            Start()
        end,
        OnDisable = function()
            if minimapIcon then minimapIcon:Apply(false) end
            Stop()
        end,
    })
end)
